import base64
import json
import sys

def decrypt_vercel(token):
    try:
        data = json.loads(base64.b64decode(token))
        # This is likely AES or similar, but let's see the structure first
        return data
    except Exception as e:
        return str(e)

tokens = {
    "SMTP_HOST": "",
    "SMTP_USER": ""
}

for k, v in tokens.items():
    print(f"{k}: {decrypt_vercel(v)}")
